<?php
declare(strict_types=1);
require dirname(__DIR__).'/Rooms.php';
use PeekaView\Rooms;
use PeekaView\Problem;
$checks=0;$outbox=[];$db=new PDO('sqlite::memory:');
function check(bool $ok,string $message):void {global $checks;++$checks;if(!$ok)throw new RuntimeException($message);}
function denied(callable $run,int $status):void {try{$run();throw new RuntimeException('Expected denial');}catch(Problem $e){check($e->status===$status,$e->getMessage());}}
$mail=function($to,$subject,$body)use(&$outbox){preg_match('/invite=([^&\s]+)/',$body,$m);$outbox[]=['token'=>$m[1],'to'=>$to];};
$service=new Rooms($db,$mail,'https://peekaview.de');
function register(string $email,string $name):array {global $service,$outbox;$service->requestDevice(['email'=>$email,'_api'=>'https://rooms.example.test/api.php']);return $service->accept(['invitation'=>end($outbox)['token'],'name'=>$name,'platform'=>'browser'],null);}
function connect(array $a,array $b):void {global $service,$outbox;$service->mutate($a['device'],'contacts/invite',['email'=>$b['device']['email'],'_api'=>'https://rooms.example.test/api.php']);$service->accept(['invitation'=>end($outbox)['token'],'name'=>$b['device']['name'],'platform'=>'browser'],$b['device']);}
$a=register('anna@example.test','Computer');$a2=register('anna@example.test','Handy');$b=register('ben@example.test','Laptop');$c=register('carla@example.test','Telefon');
connect($a,$b);connect($b,$c);
$person=$service->state($a['device'])['person']['id'];
$ben=$service->state($a['device'])['contacts'][0]['id'];
$group=$service->mutate($a['device'],'rooms/create',['name'=>'Annas Gruppe','people'=>[$ben]])['id'];
$service->mutate($a['device'],'rooms/settings',['room'=>$group,'pin_enabled'=>true,'pin'=>'Test!6']);
$service->mutate($a2['device'],'rooms/access',['room'=>$group,'unattended'=>true]);
$service->mutate($a2['device'],'rooms/invite',['room'=>$group,'email'=>'pending@example.test','_api'=>'https://rooms.example.test/api.php']);$pending=end($outbox)['token'];
$db->prepare('INSERT INTO push(device,subscription) VALUES(?,?)')->execute([$a2['device']['id'],'{}']);
$call=$service->mutate($a['device'],'calls/start',['room'=>$group,'pin'=>'Test!6'])['id'];
$service->mutate($b['device'],'calls/join',['call'=>$call,'pin'=>'Test!6']);
$service->mutate($a2['device'],'calls/auto-join',['call'=>$call]);
// Recreate the previous schema with real memberships, an active call, policy and invitation.
$db->exec('PRAGMA foreign_keys=OFF; BEGIN IMMEDIATE; CREATE TABLE previous_rooms(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner TEXT NOT NULL REFERENCES devices(id)); INSERT INTO previous_rooms SELECT r.id,r.name,(SELECT d.id FROM devices d JOIN people p ON p.email=d.email WHERE p.id=r.owner ORDER BY d.id LIMIT 1) FROM rooms r; DROP TABLE rooms; ALTER TABLE previous_rooms RENAME TO rooms; PRAGMA user_version=3; COMMIT; PRAGMA foreign_keys=ON');
$service=new Rooms($db,$mail,'https://peekaview.de');
check((int)$db->query('PRAGMA user_version')->fetchColumn()===4,'Profile ownership schema migrated');
check($service->device($a['token'])===$a['device'],'Migration preserves credentials');
check($service->state($a['device'])['rooms'][0]['owner']===$person,'Groups belong to the profile');
check($service->state($a2['device'])['rooms'][0]['can_manage'],'All own devices can still manage groups');
check($service->state($a2['device'])['rooms'][0]['unattended'],'Migration preserves per-device capture policy');
check($service->state($b['device'])['calls'][0]['id']===$call,'Migration retains the current call');
check($service->preview($pending)['room']===$group,'Migration retains pending invitations');
denied(fn()=>$service->mutate($a['device'],'devices/remove',['device'=>$b['device']['id']]),403);
check($service->device($b['token'])===$b['device'],'A foreign token remains valid');
denied(fn()=>$service->mutate($a['device'],'profile/delete',['email'=>'wrong@example.test']),400);
check($service->device($a['token'])===$a['device'],'Missing profile confirmation cannot delete data');
$service->mutate($a['device'],'devices/remove',['device'=>$a2['device']['id']]);
denied(fn()=>$service->device($a2['token']),401);
check(count($service->state($a['device'])['person']['devices'])===1,'Only the selected own device is removed');
check($service->state($a['device'])['calls']===[] && $service->state($b['device'])['calls']===[],'Revoking an admitted device ends the shared-secret call');
check((int)$db->query('SELECT COUNT(*) FROM group_access')->fetchColumn()===0,'Removed device loses unattended access');
check((int)$db->query('SELECT COUNT(*) FROM push')->fetchColumn()===0,'Removed device loses push notifications');
check($service->preview($pending)['sender_email']===$a['device']['email'],'Pending invitations continue from another own device');
$service->mutate($a['device'],'session/logout',[]);
denied(fn()=>$service->device($a['token']),401);
check((int)$db->query("SELECT COUNT(*) FROM people WHERE email='anna@example.test'")->fetchColumn()===1,'Last-device logout preserves the profile');
check((int)$db->query("SELECT COUNT(*) FROM rooms WHERE id='$group'")->fetchColumn()===1,'Last-device logout preserves owned groups');
check($service->state($b['device'])['contacts'][0]['devices']===[],'Logged-out device disappears from contact details');
check(count($service->state($b['device'])['rooms'][0]['people'])===2,'A signed-out person remains a group member without devices');
$a3=register('anna@example.test','Neuer Computer');$a4=register('anna@example.test','Neues Handy');
check($service->state($a3['device'])['person']['id']===$person,'Email login reconnects the original profile');
check($service->state($a3['device'])['rooms'][0]['id']===$group && $service->state($a3['device'])['rooms'][0]['can_manage'],'Groups remain manageable after logging in again');
check(!$service->state($a3['device'])['rooms'][0]['unattended'],'Signing in again never restores unattended access');
$people=$service->state($b['device'])['contacts'];$anna=array_values(array_filter($people,fn($p)=>$p['email']==='anna@example.test'))[0];$carla=array_values(array_filter($people,fn($p)=>$p['email']==='carla@example.test'))[0];
$other=$service->mutate($b['device'],'rooms/create',['name'=>'Bens Gruppe','people'=>[$anna['id'],$carla['id']]])['id'];
$direct=$service->mutate($a3['device'],'calls/direct',['person'=>$ben])['id'];
$unrelated=$service->mutate($b['device'],'calls/direct',['person'=>$carla['id']])['id'];
$service->mutate($c['device'],'calls/join',['call'=>$unrelated]);
$db->exec("UPDATE limits SET start=0 WHERE key='mail:anna@example.test'");
$service->requestDevice(['email'=>'anna@example.test','_api'=>'https://rooms.example.test/api.php']);$oldLogin=end($outbox)['token'];
$service->mutate($b['device'],'contacts/invite',['email'=>'anna@example.test','_api'=>'https://rooms.example.test/api.php']);$oldContact=end($outbox)['token'];
$service->mutate($a3['device'],'profile/delete',['email'=>'ANNA@example.test']);
denied(fn()=>$service->device($a3['token']),401);denied(fn()=>$service->device($a4['token']),401);
denied(fn()=>$service->preview($oldLogin),410);denied(fn()=>$service->preview($oldContact),410);
check((int)$db->query("SELECT COUNT(*) FROM people WHERE email='anna@example.test'")->fetchColumn()===0,'Profile is physically deleted');
check((int)$db->query("SELECT COUNT(*) FROM devices WHERE email='anna@example.test'")->fetchColumn()===0,'All own devices are physically deleted');
check((int)$db->query("SELECT COUNT(*) FROM rooms WHERE id='$group'")->fetchColumn()===0,'Owned group is deleted for all members');
check((int)$db->query("SELECT COUNT(*) FROM calls WHERE id='$direct'")->fetchColumn()===0,'Direct conversation and its secret are deleted');
check(count($service->state($b['device'])['rooms'])===1 && $service->state($b['device'])['rooms'][0]['id']===$other,'Groups owned by other people remain');
check(count($service->state($b['device'])['rooms'][0]['people'])===2,'Deleted profile leaves other people’s groups');
check(count($service->state($b['device'])['contacts'])===1 && $service->state($b['device'])['contacts'][0]['email']==='carla@example.test','Unrelated contacts remain');
check($service->state($b['device'])['calls'][0]['id']===$unrelated,'Unrelated calls keep running');
check($db->query('PRAGMA foreign_key_check')->fetchAll()===[],'All references remain valid after deletion');
$service=new Rooms($db,$mail,'https://peekaview.de');
check($service->state($b['device'])['calls'][0]['id']===$unrelated,'Repeated initialization preserves groups and calls');
$new=register('anna@example.test','Neuanmeldung');
check($service->state($new['device'])['person']['id']!==$person,'A deleted profile is never resurrected by a new registration');
check($service->state($new['device'])['contacts']===[] && $service->state($new['device'])['rooms']===[],'New registration cannot recover deleted contacts or groups');
$e=register('eva@example.test','Computer');$f=register('felix@example.test','Handy');
$shared=$service->mutate($e['device'],'rooms/create',['name'=>'Gemeinsame Gruppe'])['id'];
$service->mutate($e['device'],'rooms/invite',['room'=>$shared,'email'=>$f['device']['email'],'_api'=>'https://rooms.example.test/api.php']);
$service->accept(['invitation'=>end($outbox)['token'],'name'=>'Handy','platform'=>'browser'],$f['device']);
$service->mutate($f['device'],'session/logout',[]);
check($service->state($e['device'])['contacts'][0]['email']==='felix@example.test','A contact known through a group survives last-device logout');
check($service->state($e['device'])['contacts'][0]['devices']===[],'Shared-group contact has no signed-in device');
$f2=register('felix@example.test','Neues Handy');
check($service->state($f2['device'])['rooms'][0]['id']===$shared,'Group membership returns when the person signs in again');
echo "$checks Konto-/Geräteprüfungen erfolgreich.\n";
